// Ambient module declarations for static image imports (Vite resolves these
// to URLs at build time). Added so `import logo from '...png'` type-checks.
declare module '*.png' {
  const src: string;
  export default src;
}
declare module '*.jpg' {
  const src: string;
  export default src;
}
declare module '*.svg' {
  const src: string;
  export default src;
}
declare module '*.webp' {
  const src: string;
  export default src;
}
